import{_ as s,o as i,c as t,a5 as n}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"ネイティブビルドと IL2CPP","description":"","frontmatter":{"title":"ネイティブビルドと IL2CPP","study":{"source":"C++ Wiki","kind":"本文","status":"既存原稿","summary":"IL2CPPは「C#(IL)をC++ソースに変換し、各プラットフォームのC++コンパイラでビルドする」Unityの仕組み。つまりあなたのC#コードは、最終的に本Wiki第6部の旅を通ってCPU命令になっています。C++を学ぶと、IL2CPPの制約・性能特性が「仕様の暗記」から「当然の帰結」に変わりま"}},"headers":[],"relativePath":"languages/csharp/il2cpp.md","filePath":"languages/csharp/il2cpp.md"}'),e={name:"languages/csharp/il2cpp.md"};function l(p,a,h,r,d,o){return i(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="ネイティブビルドと-il2cpp" tabindex="-1">ネイティブビルドと IL2CPP <a class="header-anchor" href="#ネイティブビルドと-il2cpp" aria-label="Permalink to &quot;ネイティブビルドと IL2CPP&quot;">​</a></h1><h2 id="一言で言うと" tabindex="-1">一言で言うと <a class="header-anchor" href="#一言で言うと" aria-label="Permalink to &quot;一言で言うと&quot;">​</a></h2><p>IL2CPPは「<strong>C#(IL)をC++ソースに変換し、各プラットフォームのC++コンパイラでビルドする</strong>」Unityの仕組み。つまりあなたのC#コードは、最終的に<a href="/study/runtime/cpp-internals/build-pipeline-journey.html">本Wiki第6部の旅</a>を通ってCPU命令になっています。C++を学ぶと、IL2CPPの制約・性能特性が「仕様の暗記」から「当然の帰結」に変わります。</p><h2 id="実行方式の全体地図" tabindex="-1">実行方式の全体地図 <a class="header-anchor" href="#実行方式の全体地図" aria-label="Permalink to &quot;実行方式の全体地図&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C#ソース ──Roslyn──&gt; IL(中間言語)+メタデータ</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    ├─ [Mono/JIT]     実行時にILを機械語へ(エディタ再生、一部プラットフォーム)</span></span>
<span class="line"><span>    │                  柔軟(実行時コード生成OK)だが、起動後の変換コスト・JIT不可の環境あり</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └─ [IL2CPP/AOT]   ビルド時にIL→C++→機械語(iOS・コンソールは事実上必須)</span></span>
<span class="line"><span>                       il2cpp.exe が .cpp を吐き、MSVC/Clang等が旅の②以降を実行</span></span></code></pre></div><ul><li>AOT (Ahead-Of-Time) = 事前コンパイル。JIT禁止のプラットフォーム(iOS等)で必須</li><li>生成されたC++は <code>Library/Il2cppBuildCache</code> 等で実際に読める(C++を学んだ今なら!)</li></ul><h2 id="il2cppの制約をc-の知識で説明する" tabindex="-1">IL2CPPの制約をC++の知識で説明する <a class="header-anchor" href="#il2cppの制約をc-の知識で説明する" aria-label="Permalink to &quot;IL2CPPの制約をC++の知識で説明する&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Unityでの経験則</th><th>C++側の理由</th></tr></thead><tbody><tr><td>実行時のコード生成(Emit)不可</td><td>機械語は事前に全部作る。実行時にコンパイラはいない(<a href="/study/languages/csharp/templates-vs-generics.html">テンプレートとジェネリック</a>と同じ構図)</td></tr><tr><td>値型ジェネリックの組み合わせがAOTで漏れる</td><td>ジェネリックがC++テンプレート的に<strong>使用実績ベースで実体化</strong>されるため、リフレクション経由でしか現れない組み合わせは生成されない</td></tr><tr><td>コードストリッピングでメソッドが消える(link.xml)</td><td>リンカのデッドコード除去(<a href="/study/runtime/cpp-internals/object-files-and-libraries.html">リンク</a>)。リフレクション呼び出しは「使用」と見なされない</td></tr><tr><td>iOSビルドが遅い</td><td>生成された膨大なC++のコンパイル(<a href="/study/tools/build/build-speed.html">ビルドが遅い理由</a>がフル適用)</td></tr><tr><td>IL2CPPの方が速いことが多い</td><td>C++コンパイラの最適化(<a href="/study/runtime/cpp-internals/optimization-and-ub.html">第6部</a>)がフルに掛かる。ただしGCはBoehmのまま(→ <a href="/study/runtime/memory/gc-and-csharp-comparison.html">GC比較</a>)</td></tr></tbody></table><h2 id="ネイティブプラグインとの境界-p-invoke" tabindex="-1">ネイティブプラグインとの境界(P/Invoke) <a class="header-anchor" href="#ネイティブプラグインとの境界-p-invoke" aria-label="Permalink to &quot;ネイティブプラグインとの境界(P/Invoke)&quot;">​</a></h2><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// C#側</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">DllImport</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;gamephysics&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)]                     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ネイティブDLL/静的ライブラリの関数を呼ぶ</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">private</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> static</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> extern</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Simulate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dt</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// C++側 — extern &quot;C&quot; でC ABIに固定(→ シンボルと名前修飾)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">extern</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;C&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> __declspec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(dllexport) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Simulate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">float</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dt) {</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> /* ... */</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> return</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; }</span></span></code></pre></div><ul><li>境界のルールは<a href="/study/runtime/cpp-internals/object-files-and-libraries.html">DLLのページ</a>そのまま: <strong>C ABI+プレーンなデータ</strong>(構造体はblittableに=参照型・stringを含めない)</li><li>呼び出しコストは1回あたり数十〜数百サイクル(マーシャリング)。<strong>細かく何度も呼ばず、まとめて渡す</strong>(配列でバッチ)が定石</li><li>文字列・配列の受け渡しは所有権を明確に(「C#側のメモリをC++が覚えてはいけない」——GCが動かす/回収するため。pinningの概念)</li></ul><h2 id="burstとの関係" tabindex="-1">Burstとの関係 <a class="header-anchor" href="#burstとの関係" aria-label="Permalink to &quot;Burstとの関係&quot;">​</a></h2><p>Burst(HPC# → LLVMで機械語)は「C#の<strong>サブセット</strong>を、C++並みの最適化で直接コンパイルする」別ルート。IL2CPPが「C#全部をそこそこ速いC++に」なのに対し、Burstは「制限つきC#(<a href="/study/game/patterns/optimization-patterns.html">Data Locality</a>前提の書き方)を最速に」。<strong>制限の内容(参照型禁止・NativeContainer)は、本Wikiで学んだ「速いC++の条件」そのもの</strong>です。</p><h2 id="unity開発者が誤解しやすい点" tabindex="-1">Unity開発者が誤解しやすい点 <a class="header-anchor" href="#unity開発者が誤解しやすい点" aria-label="Permalink to &quot;Unity開発者が誤解しやすい点&quot;">​</a></h2><ol><li>「IL2CPPにすればC++の速さになる」— 変換されるのはコード。<strong>GCと管理ヒープの構造はそのまま</strong>なので、Allocのスパイクは消えない</li><li>「エディタで動けば実機でも動く」— エディタはMono/JIT。AOT制約・ストリッピング・C++最適化の差でIL2CPP実機のみのバグは普通にある(→ <a href="/study/tools/build/build-configurations.html">Debug/Release差</a>と同じ構図)</li><li>生成C++を「読めない魔法」と思わない——変数名は機械的だが、構造は本Wikiで学んだC++そのもの。実機クラッシュの解析で読む日が来る</li></ol><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li>JITとAOTの違いと、iOSでAOTが必須な理由は?</li><li>AOTジェネリック問題とコードストリッピング問題を、C++の語彙(実体化・デッドコード除去)で説明できますか。</li><li>P/Invoke境界の設計ルールを2つ挙げてください。</li></ol><h2 id="演習" tabindex="-1">演習 <a class="header-anchor" href="#演習" aria-label="Permalink to &quot;演習&quot;">​</a></h2><p>自分のUnityプロジェクト(またはサンプルプロジェクト)をIL2CPPでビルドし、生成されたC++(Il2cppBuildCache)から自作クラスに対応するファイルを探して眺めてください。「C#のクラスがC++でどう表現されているか」を3点メモしてください(メソッドテーブル、nullチェックの挿入、など)。</p><hr><p>前: <a href="/study/languages/csharp/headers-vs-asmdef.html">ヘッダー分割とAssembly Definition</a> | <a href="/study/languages/csharp/">カテゴリ目次</a> | 次: <a href="/study/languages/csharp/memory-management-vs-gc.html">手動メモリ管理とGC</a></p>`,22)])])}const u=s(e,[["render",l]]);export{c as __pageData,u as default};
